always @(posedge clk) begin
if (L) begin
q <= r;
end else begin
q <= {q[1] ^ q[2], q[0], q[2]};
end
end
endmodule
module top_module(
input clk,
input L,
input q_in,
input r_in,
output reg Q
);
wire [2:0] r;
wire [2:0] q;
full_module full1(
.r(r_in),
.L(L),
.clk(clk),
.q(q[0])
);
full_module full2(
.r(q[0]),
.L(L),
.clk(clk),
.q(q[1])
);
full_module full3(
.r(q[1]),
.L(L),
.clk(clk),
.q(q[2])
);
always @(posedge clk) begin
if (L) begin
Q <= q_in;
end else begin
Q <= {q[1] ^ q[2], q[0], q[2]};
end
end
endmodule

